"""Random starting points, step caps and target sequences, including targets
that jump both up and down across the same run."""


def generate(rng, count):
    builders = (_random_targets, _alternating, _tight_cap)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, start, max_step, targets, description=""):
    lines = ["%d %d" % (start, max_step)]
    lines.extend(str(t) for t in targets)
    return {"name": name, "stdin": "\n".join(lines) + "\n",
            "description": description}


def _random_targets(rng, index):
    start = rng.randint(-100, 100)
    max_step = rng.randint(1, 20)
    targets = [rng.randint(-200, 200) for _ in range(6)]
    return _case("random targets #%d" % index, start, max_step, targets)


def _alternating(rng, index):
    max_step = rng.randint(5, 15)
    targets = [200, -200, 200, -200]
    return _case("a target that reverses every step #%d" % index, 0,
                 max_step, targets,
                 "The demand swings from one extreme to the other -- both "
                 "directions of the cap get exercised.")


def _tight_cap(rng, index):
    start = rng.randint(-10, 10)
    target = start + rng.randint(1, 5)
    return _case("a cap wider than the whole move #%d" % index, start, 100,
                 [target] * 3,
                 "max_step is larger than the distance to the target -- "
                 "the output should land on it in one step and then hold.")
